package org.jsoup.safety;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.*;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.safety.Whitelist;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Cleaner_clean_TriageGen1Test {

    private Cleaner cleaner;

    @Before
    public void setUp() {
        cleaner = new Cleaner(Whitelist.none());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testClean_NullDocument() {
        cleaner.clean(null);
    }

    @Test
    public void testClean_EmptyDocument() {
        Document dirtyDocument = Document.createShell("");
        Document cleanDocument = cleaner.clean(dirtyDocument);
        assertNotNull(cleanDocument);
        assertEquals("", cleanDocument.outerHtml());
    }

    @Test
    public void testClean_SimpleDocument() {
        Document dirtyDocument = Document.createShell("http://example.com").body().appendElement("p").text("Hello, World!");
        Document cleanDocument = cleaner.clean(dirtyDocument);
        assertNotNull(cleanDocument);
        assertTrue(cleanDocument.body().children().isEmpty());
    }

    @Test
    public void testClean_ContainsOnlySafeTags() {
        Document dirtyDocument = Document.createShell("http://example.com")
                .body()
                .appendElement("p")
                .text("Safe content");
        cleaner = new Cleaner(Whitelist.simpleText());
        Document cleanDocument = cleaner.clean(dirtyDocument);
        assertNotNull(cleanDocument);
        assertEquals("Safe content", cleanDocument.body().text());
    }

    @Test
    public void testClean_InvalidDocument() {
        Document dirtyDocument = Document.createShell("http://example.com").body().appendElement("script").text("alert('XSS');");
        assertFalse(cleaner.isValid(dirtyDocument));
    }

    @Test
    public void testCleanWithCustomWhitelist() {
        Cleaner customCleaner = new Cleaner(Whitelist.none().addTags("p", "a"));
        Document dirtyDocument = Document.createShell("http://example.com")
                .body()
                .appendElement("p")
                .text("Paragraph with <a href='#'>link</a>");
        Document cleanDocument = customCleaner.clean(dirtyDocument);
        assertNotNull(cleanDocument);
        assertEquals("<p>Paragraph with <a href=\"#\">link</a></p>", cleanDocument.body().html());
    }

    @Test
    public void testClean_InvalidTagWithCustomWhitelist() {
        Cleaner customCleaner = new Cleaner(Whitelist.none().addTags("p"));
        Document dirtyDocument = Document.createShell("http://example.com")
                .body()
                .appendElement("p")
                .appendElement("script")
                .text("alert('XSS');");
        Document cleanDocument = customCleaner.clean(dirtyDocument);
        assertNotNull(cleanDocument);
        assertEquals("<p></p>", cleanDocument.body().html());
    }
}
